pub(crate) const STYLES: &str = r#"
.df-character{--gold:#dfb974;--muted:#b6bec6;--ink:#070d14;position:relative;isolation:isolate;min-height:100svh;background:var(--ink);color:#f5eee0;font-family:Georgia,'Times New Roman',serif;overflow:hidden}
.df-character *{box-sizing:border-box;min-width:0}.df-character [hidden]{display:none!important}.df-character p,.df-character h1,.df-character h2,.df-character button,.df-character dd{overflow-wrap:anywhere}.df-character .character-backdrop{position:absolute;inset:0;width:100%;height:680px;object-fit:cover;object-position:center 42%;z-index:-3;opacity:.48}.df-character:before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,#03080f80,#070d1480 220px,#070d14 650px)}
.df-character .character-header{padding:25px 4vw;display:flex;justify-content:space-between;align-items:center;gap:20px;border-bottom:1px solid #dbc18b26;background:#08111b55}.df-character .character-brand{font-size:31px;letter-spacing:-1.3px;color:#f3d59d}.df-character .character-brand span{color:#b9d8e9}.df-character .character-overline{font:10px/1.7 system-ui,sans-serif;letter-spacing:2.5px;text-transform:uppercase;color:var(--gold)}
.df-character .character-hero{width:min(1380px,92vw);margin:auto;padding:58px 0 35px}.df-character h1{font-size:clamp(40px,5vw,70px);font-weight:400;letter-spacing:-1.8px;line-height:1.1;margin:14px 0 20px}.df-character .character-description{max-width:670px;color:#d8d7d0;font-size:18px;line-height:1.65;margin:0}.df-character .character-layout{width:min(1380px,92vw);margin:auto;display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:28px;align-items:start;padding-bottom:35px}.df-character .character-workshop,.df-character .character-groups{display:grid;gap:24px}.df-character .character-panel{border:1px solid #ad925d55;border-radius:4px;background:linear-gradient(140deg,#0c1721ef,#08101cf5);padding:26px;box-shadow:0 15px 40px #0003}.df-character h2{font-size:24px;line-height:1.3;font-weight:400;margin:0 0 20px;color:#ebd4aa}.df-character .character-group-description{font:13px/1.7 system-ui,sans-serif;color:var(--muted);margin:0 0 21px}.df-character .character-summary{position:sticky;top:24px}.df-character .character-portrait{display:block;width:100%;height:190px;object-fit:cover;object-position:center 35%;border:1px solid #bea06570;border-radius:3px;background:#111c28;margin:19px 0 8px}.df-character .character-art-credit{font:10px/1.6 system-ui,sans-serif;color:#a1aebc;margin:8px 0 24px}.df-character .character-status{font-size:23px;margin-bottom:12px}.df-character .character-message{font:13px/1.7 system-ui,sans-serif;color:#bfccd5;margin:0 0 22px}.df-character[data-status=rejected] .character-message{color:#ffc2b3}.df-character[data-status=ready] .character-status,.df-character[data-status=locked] .character-status{color:#b5ddc2}
.df-character .df-ui-field{margin-top:18px;display:grid;gap:6px}.df-character .df-ui-field label{display:grid;gap:8px;font:12px/1.5 system-ui,sans-serif;color:#c8d0d8}.df-character input{width:100%;min-height:48px;padding:12px 14px;border:1px solid #a7b3c045;border-radius:3px;color:#f5eee0;background:#08111dcc;font:16px/1.5 system-ui,sans-serif}.df-character input[readonly]{color:#adb9c4;background:#101925}.df-character input[aria-invalid=true]{border-color:#d99582}.df-character .df-ui-feedback{font:12px/1.6 system-ui,sans-serif;color:#eab59f;margin:0;min-height:0}.df-character .df-ui-feedback:empty{display:none}
.df-character .character-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.df-character .character-option{position:relative;border:1px solid #a2afbf33;border-radius:3px;padding:19px;background:#0a1424cc;display:flex;flex-direction:column;gap:12px;transition:border-color .15s,background .15s}.df-character .character-option[data-selected=true]{border-color:#d0ae72;background:#6b50242b}.df-character .character-option[data-selected=true]:before{content:'Selected';font:9px/1.4 system-ui,sans-serif;letter-spacing:1px;text-transform:uppercase;color:#e8ca91;position:absolute;top:9px;right:10px}.df-character .option-portrait{width:52px;height:52px;object-fit:cover;border-radius:50%;border:1px solid #c5a86b77;background:#152332}.df-character .option-description{font:13px/1.7 system-ui,sans-serif;color:#c4ced7;margin:0}.df-character .option-availability{font:10px/1.6 system-ui,sans-serif;color:#96a8b8;margin:0 0 auto}.df-character button{touch-action:manipulation;min-height:46px;width:100%;font:13px/1.4 system-ui,sans-serif;letter-spacing:.3px;border:1px solid #c6a56866;border-radius:3px;padding:12px 16px;color:#eed3a0;background:#6b50242c;cursor:pointer}.df-character button:hover:enabled{background:#6b502455;border-color:#dfb974}.df-character button[aria-pressed=true]{border-color:#dfb974;background:#84602d50}.df-character button:disabled{cursor:default;color:#9fabb8;border-color:#8897a32f;background:#0c1725}.df-character :focus-visible{outline:3px solid #9ddbff;outline-offset:4px}.df-character .character-facts{margin:0 0 25px}.df-character .character-fact{display:flex;justify-content:space-between;gap:15px;border-top:1px solid #ad925d33;padding:12px 0;font:12px/1.6 system-ui,sans-serif}.df-character dt{color:#a2b2c2}.df-character dd{margin:0;text-align:right;color:#e1d6c0}.df-character .character-actions{display:grid;gap:10px}.df-character .character-reference{width:min(1380px,92vw);margin:0 auto 30px;border-top:1px solid #b69b6355;padding-top:25px}.df-character summary{min-height:44px;color:#dfbd80;cursor:pointer;font:18px/1.5 Georgia,serif}.df-character .character-reference img{display:block;width:100%;max-width:1000px;border:1px solid #ad925d55}.df-character .character-connection{padding:10px 4vw 30px;text-align:center;color:#98a7b5;font:11px/1.7 system-ui,sans-serif}.df-character .character-fixture-controls{width:min(1380px,92vw);margin:0 auto 30px;display:flex;flex-wrap:wrap;gap:10px}.df-character .character-fixture-controls button{width:auto}.df-character .character-fixture-output{width:min(1380px,92vw);margin:0 auto 24px;color:#b9c8d6;font:12px/1.7 system-ui,sans-serif}
.df-character .character-portrait,.df-character .option-portrait{position:relative;overflow:hidden;flex-shrink:0;background:radial-gradient(ellipse at 50% 35%,#29404d,#101d2a 75%)}.df-character .portrait-bitmap{position:absolute;inset:0;display:block;width:100%;height:100%;object-fit:cover;object-position:center 35%;border-radius:inherit}.df-character .portrait-fallback{position:absolute;inset:0;display:block;color:#d7bc84}.df-character .portrait-fallback:before{content:'';position:absolute;left:50%;top:20%;transform:translateX(-50%);width:26%;height:29%;border:1px solid currentColor;border-radius:50%;background:#c5ab7433}.df-character .portrait-fallback:after{content:'';position:absolute;left:50%;top:54%;transform:translateX(-50%);width:65%;height:47%;border:1px solid currentColor;border-radius:50% 50% 0 0;background:#c5ab7422}.df-character .character-portrait .portrait-fallback{max-width:140px;left:50%;transform:translateX(-50%);width:100%}
@media(max-width:1000px){.df-character .character-layout{grid-template-columns:minmax(0,1fr) 280px;gap:20px}.df-character .character-panel{padding:20px}.df-character .character-options{grid-template-columns:1fr}.df-character .character-hero{padding-top:45px}}
@media(max-width:700px){.df-character .character-header{padding:20px 5vw;align-items:start}.df-character .character-header .character-overline{max-width:120px;text-align:right;font-size:8px}.df-character .character-brand{font-size:27px}.df-character .character-hero{width:90vw;padding:40px 0 28px}.df-character h1{letter-spacing:-1px;font-size:43px}.df-character .character-description{font-size:16px}.df-character .character-layout{display:flex;flex-direction:column;width:90vw;gap:24px}.df-character .character-workshop,.df-character .character-summary{width:100%;position:static}.df-character .character-options{grid-template-columns:1fr}.df-character .character-portrait{height:230px}.df-character .character-panel{padding:22px}.df-character .character-reference{width:90vw}.df-character .character-fixture-controls{width:90vw}.df-character .character-fixture-controls button{flex:1 1 130px}.df-character .character-fixture-output{width:90vw}}
@media(prefers-reduced-motion:reduce){.df-character *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
"#;
